<script setup>
import { computed,ref } from "vue";
import { useRoute,useRouter } from "vue-router";
import AuthLayout from "../../layouts/AuthLayout.vue";
import { login } from "../../services/auth.service";
import { useAuthStore } from "../../stores/auth.store";
import { language,setLanguage } from "../../i18n/index.js";
import "./sign-in-mobile.css";

const email=ref("");const password=ref("");const showPassword=ref(false);const loading=ref(false);const errorMessage=ref("");
const router=useRouter();const route=useRoute();const auth=useAuthStore();
const sessionMessage=computed(()=>({expired:"Your session expired. Sign in again to continue.",inactive:"You were signed out after a period of inactivity.",session_expired:"Your session ended. Sign in again to continue.",signed_out:"You have been signed out securely."}[route.query.reason]||""));
const submit=async()=>{if(!email.value||!password.value){errorMessage.value="Enter your email address and password.";return;}loading.value=true;errorMessage.value="";try{const response=await login({email:email.value,password:password.value,language:language.value});auth.setAuth(response.data.token,response.data.language,response.data.organization);setLanguage(response.data.language);await router.replace("/dashboard");}catch(error){errorMessage.value=error.response?.data?.message||"The email or password is incorrect.";}finally{loading.value=false;}};
</script>

<template><AuthLayout><main class="signin-page"><section class="signin-card"><header><router-link class="brand" to="/login"><span>V</span><div><strong>Vikoba</strong><small>Group Finance Platform</small></div></router-link><label><i class="bi bi-globe2"></i><select :value="language" @change="setLanguage($event.target.value)"><option value="en">English</option><option value="sw">Kiswahili</option></select></label></header><div class="heading"><router-link to="/login"><i class="bi bi-arrow-left"></i> Back to website</router-link><span>Welcome back</span><h1>Sign in to your account</h1><p>Enter your details to open your group workspace.</p></div><form @submit.prevent="submit"><div v-if="sessionMessage" class="message info"><i class="bi bi-info-circle"></i>{{ sessionMessage }}</div><div v-if="errorMessage" class="message error"><i class="bi bi-exclamation-circle"></i>{{ errorMessage }}</div><label>Email address<div class="input"><i class="bi bi-envelope"></i><input v-model.trim="email" type="email" autocomplete="email" placeholder="you@example.com" required autofocus></div></label><label>Password<div class="input"><i class="bi bi-lock"></i><input v-model="password" :type="showPassword?'text':'password'" autocomplete="current-password" placeholder="Enter your password" required><button type="button" :aria-label="showPassword?'Hide password':'Show password'" @click="showPassword=!showPassword"><i class="bi" :class="showPassword?'bi-eye-slash':'bi-eye'"></i></button></div></label><button class="submit" :disabled="loading"><span v-if="loading" class="spinner-border spinner-border-sm"></span>{{ loading?'Signing in...':'Sign in' }}<i v-if="!loading" class="bi bi-arrow-right"></i></button></form><p class="trial">New group? <router-link to="/start-trial">Start a 7-day free trial</router-link></p></section><aside><div><span>Secure group finance</span><h2>Every transaction. Every approval. One trusted record.</h2><p>Continue managing your members, finances, meetings, reports, and cycle share-outs.</p></div><ul><li><i class="bi bi-shield-check"></i>Role-based financial controls</li><li><i class="bi bi-journal-check"></i>Complete audit history</li><li><i class="bi bi-lock"></i>Isolated and protected group data</li></ul></aside></main></AuthLayout></template>

